-- BrainRush: Arabic translations for the seeded questions and answers.
--
-- Requires sql/migrate-add-arabic.sql (or a schema that already has question_ar / answer_ar).
-- Rows are matched by their English question text, so ids do not matter and it works on
-- the hosted database too. Only questions with no Arabic yet are filled: text entered in
-- the admin is never overwritten. Safe to run again.
--   local:   mysql -u root brainrush < sql/add-arabic-translations.sql
--   hosted:  phpMyAdmin -> select the database -> Import this file
--
-- NOTE: drafted by an AI assistant. Have an Arabic speaker review the wording before
-- using it on the live site.

SET NAMES utf8mb4;

CREATE TEMPORARY TABLE arabic_seed (
  question    TEXT NOT NULL,
  question_ar TEXT NOT NULL,
  answer_ar   TEXT NOT NULL
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;


UPDATE questions q
  JOIN arabic_seed s ON s.question = q.question
   SET q.question_ar = s.question_ar,
       q.answer_ar   = s.answer_ar
 WHERE q.question_ar IS NULL AND q.answer_ar IS NULL;

DROP TEMPORARY TABLE arabic_seed;
